import boto3

bedrock = boto3.client('bedrock-runtime')

def stream_completion(prompt):
    model_id = 'amazon.titan-text-express-v1'
    body = {
        'inputText': prompt,
        'textGenerationConfig': {
            'maxTokenCount': 500,
            'stopSequences': [],
            'temperature': 0.5,
            'topP': 0.9
        }
    }

    response = bedrock.invoke_model(
        body=json.dumps(body),
        modelId=model_id,
        accept='application/json',
        contentType='application/json'
    )

    response_body = json.loads(response.get('body').read())
    output_text = response_body.get('results')[0].get('outputText')

    for token in output_text:
        yield token

import boto3

from botocore.exceptions import NoCredentialsError, PartialCredentialsError


class AnswerWithContext:
    def __init__(self, region_name='us-west-2'):
        self.region_name = region_name
        self.bedrock = boto3.client('bedrock-runtime', region_name=self.region_name)

    def answer_question(self, question, context):
        try:
            response = self.bedrock.invoke_model(
                modelId='amazon.titan-text-express-v1',
                body={
                    'inputText': f"Answer the following question using the provided context: {question}. Context: {context}",
                    'textGenerationConfig': {
                        'maxTokenCount': 4096,
                        'stopSequences': [],
                        'temperature': 0.5,
                        'topP': 0.9
                    }
                }
            )
            result = json.loads(response['body'].read())
            return result['results'][0]['outputText']
        except (NoCredentialsError, PartialCredentialsError) as e:
            print(f"Error: {e}")
            return None


if __name__ == '__main__':
    answerer = AnswerWithContext()
    question = 'What is the capital of France?'
    context = 'France is a country in Europe. The capital of France is Paris.'
    answer = answerer.answer_question(question, context)
    print(f"Answer: {answer}")

import boto3

def extract_json(text):
    bedrock = boto3.client('bedrock-runtime')
    response = bedrock.invoke_model(
        model_id='amazon.bedrock.model',
        body={
            'prompt': text,
            'max_tokens': 150
        }
    )
    result = response['body'].read()
    return result

import boto3

def summarize_text(text):
    bedrock = boto3.client('bedrock')
    response = bedrock.invoke_model(
        model_id='amazon.bedrock.summarization',
        body={
            'inputText': text
        }
    )
    return response['summary']
